extends SceneTree
# A6 Effect A, jump puff (CHANGE-BRIEF A3): loads res://effects/jump_puff.tscn and reads every
# setting the brief names back from the loaded nodes and resources, against the brief's values.
# A Godot 3 or misspelt name in the scene (prediction P1) is dropped on load, so its read-back
# shows the engine default instead of the brief's value and the check fails.
# Run: scripts/run-test.sh test_jump_puff_config.gd 60
# What this cannot see: the look. Headless Godot draws no particles (CLAUDE.md, Headless facts).
const SCENE_PATH := "res://effects/jump_puff.tscn"
const ORDER := ["Flash", "Puff", "Specks"]
var results: Array[Dictionary] = []
var failures := 0

# CHANGE-BRIEF A3 settings table, one column per emitter; "—" cells are left out. preprocess and
# use_fixed_seed come from the bullets under the table ("No preprocess (0)"; "the effect scene
# never does" set a seed).
var brief := {
	"Flash": {
		"amount": 1, "one_shot": true, "explosiveness": 1.0, "lifetime": 0.12, "lifetime_randomness": 0.0,
		"emission_shape": CPUParticles2D.EMISSION_SHAPE_POINT,
		"initial_velocity_min": 0.0, "initial_velocity_max": 0.0, "gravity": Vector2(0, 0),
		"damping_min": 0.0, "damping_max": 0.0, "angle_min": 0.0, "angle_max": 0.0,
		"angular_velocity_min": 0.0, "angular_velocity_max": 0.0,
		"scale_amount_min": 0.6, "scale_amount_max": 0.6,
		"hue_variation_min": 0.0, "hue_variation_max": 0.0,
		"local_coords": false, "preprocess": 0.0, "use_fixed_seed": false,
	},
	"Puff": {
		"amount": 10, "one_shot": true, "explosiveness": 1.0, "lifetime": 0.9, "lifetime_randomness": 0.2,
		"emission_shape": CPUParticles2D.EMISSION_SHAPE_SPHERE, "emission_sphere_radius": 3.0,
		"direction": Vector2(0, -1), "spread": 80.0,
		"initial_velocity_min": 50.0, "initial_velocity_max": 90.0, "gravity": Vector2(0, -20),
		"damping_min": 250.0, "damping_max": 300.0, "angle_min": 0.0, "angle_max": 360.0,
		"angular_velocity_min": -90.0, "angular_velocity_max": 90.0,
		"scale_amount_min": 0.5, "scale_amount_max": 0.8,
		"hue_variation_min": -0.02, "hue_variation_max": 0.02,
		"local_coords": false, "preprocess": 0.0, "use_fixed_seed": false,
	},
	"Specks": {
		"amount": 6, "one_shot": true, "explosiveness": 1.0, "lifetime": 0.45, "lifetime_randomness": 0.25,
		"emission_shape": CPUParticles2D.EMISSION_SHAPE_SPHERE, "emission_sphere_radius": 4.0,
		"direction": Vector2(0, -1), "spread": 60.0,
		"initial_velocity_min": 80.0, "initial_velocity_max": 150.0, "gravity": Vector2(0, 600),
		"damping_min": 0.0, "damping_max": 0.0, "angle_min": 0.0, "angle_max": 0.0,
		"angular_velocity_min": 0.0, "angular_velocity_max": 0.0,
		"scale_amount_min": 0.08, "scale_amount_max": 0.14,
		"hue_variation_min": 0.0, "hue_variation_max": 0.0,
		"local_coords": false, "preprocess": 0.0, "use_fixed_seed": false,
	},
}
# scale_amount_curve as (offset, value) points; null = "none".
var scale_curves := {
	"Flash": [Vector2(0, 1.0), Vector2(1, 0.3)],
	"Puff": [Vector2(0, 0.6), Vector2(0.3, 1.0), Vector2(1.0, 1.3)],
	"Specks": null,
}
# color_ramp as [offset, colour] stops.
var color_ramps := {
	"Flash": [[0.0, Color(1, 1, 1, 0.9)], [1.0, Color(1, 1, 1, 0.0)]],
	"Puff": [[0.0, Color(0.97, 0.96, 0.94, 0.95)], [0.35, Color(0.62, 0.63, 0.68, 0.7)], [1.0, Color(0.45, 0.47, 0.52, 0.0)]],
	"Specks": [[0.0, Color(Color("25354a"), 1.0)], [1.0, Color(Color("25354a"), 0.0)]],
}
# "Draw": one GradientTexture2D in the scene file, white α 1 → white α 0.
var disc := {"width": 32, "height": 32, "fill": GradientTexture2D.FILL_RADIAL, "fill_from": Vector2(0.5, 0.5), "fill_to": Vector2(1.0, 0.5)}
var disc_stops := [[0.0, Color(1, 1, 1, 1)], [1.0, Color(1, 1, 1, 0)]]

func _initialize() -> void:
	call_deferred("run")

func check(id: String, condition: bool, observed: Dictionary) -> void:
	results.append({"id": id, "status": "PASS" if condition else "FAIL", "observed": observed})
	print(JSON.stringify(results.back()))
	if not condition:
		failures += 1

# Floats within is_equal_approx (scene values are stored as 32-bit floats); everything else exact.
func same(got, want) -> bool:
	match typeof(want):
		TYPE_FLOAT:
			return typeof(got) in [TYPE_FLOAT, TYPE_INT] and is_equal_approx(float(got), want)
		TYPE_VECTOR2:
			return typeof(got) == TYPE_VECTOR2 and got.is_equal_approx(want)
		TYPE_COLOR:
			return typeof(got) == TYPE_COLOR and got.is_equal_approx(want)
		_:
			return typeof(got) == typeof(want) and got == want

# JSON-safe form of a value for the log.
func shown(v):
	return v if typeof(v) in [TYPE_NIL, TYPE_BOOL, TYPE_INT, TYPE_FLOAT, TYPE_STRING] else str(v)

func embedded(res: Resource) -> bool:
	return res != null and res.resource_path.begins_with(SCENE_PATH + "::")

func stops_of(g: Gradient) -> Array:
	var out := []
	if g != null:
		for i in g.get_point_count():
			out.append([g.get_offset(i), g.get_color(i)])
	return out

func same_stops(got: Array, want: Array) -> bool:
	if got.size() != want.size():
		return false
	for i in want.size():
		if not (same(got[i][0], want[i][0]) and same(got[i][1], want[i][1])):
			return false
	return true

func points_of(c: Curve) -> Array:
	var out := []
	if c != null:
		for i in c.point_count:
			out.append(c.get_point_position(i))
	return out

func same_points(got: Array, want: Array) -> bool:
	if got.size() != want.size():
		return false
	for i in want.size():
		if not same(got[i], want[i]):
			return false
	return true

func run() -> void:
	var packed: PackedScene = load(SCENE_PATH)
	check("scene-loads", packed != null, {"path": SCENE_PATH})
	if packed == null:
		quit(1)
		return
	var puff: Node = packed.instantiate()

	# --- A3: Node2D root JumpPuff, three CPUParticles2D children Flash, Puff, Specks ---
	var kids := []
	for c in puff.get_children():
		kids.append("%s:%s" % [c.name, c.get_class()])
	var shape_ok: bool = puff.name == "JumpPuff" and puff.get_class() == "Node2D" and puff.get_child_count() == ORDER.size()
	for i in ORDER.size():
		shape_ok = shape_ok and i < puff.get_child_count() and puff.get_child(i).name == ORDER[i] and puff.get_child(i).get_class() == "CPUParticles2D"
	check("structure", shape_ok, {"root": "%s:%s" % [puff.name, puff.get_class()], "children": kids, "expected": ["Flash:CPUParticles2D", "Puff:CPUParticles2D", "Specks:CPUParticles2D"]})

	# --- A3: "No draw material: default mix blend" ---
	check("root.material", puff.material == null, {"read_back": str(puff.material), "expected": "none (mix blend)"})

	var textures := []
	for emitter_name in ORDER:
		var e: Node = puff.get_node_or_null(emitter_name)
		if e == null:
			check(emitter_name, false, {"missing": emitter_name})
			continue
		var want: Dictionary = brief[emitter_name]
		for prop in want:
			var got = e.get(prop)
			check("%s.%s" % [emitter_name, prop], same(got, want[prop]), {"expected": shown(want[prop]), "read_back": shown(got)})

		# scale_amount_curve: a Curve inside the scene with the brief's points, or none.
		var curve = e.get("scale_amount_curve")
		var want_pts = scale_curves[emitter_name]
		if want_pts == null:
			check("%s.scale_amount_curve" % emitter_name, curve == null, {"expected": "none", "read_back": str(curve)})
		else:
			var pts := points_of(curve) if curve is Curve else []
			check("%s.scale_amount_curve" % emitter_name, curve is Curve and embedded(curve) and same_points(pts, want_pts),
				{"expected_points": str(want_pts), "read_back_points": str(pts), "type": str(curve), "in_scene_file": embedded(curve) if curve is Resource else false})

		# color_ramp: a Gradient inside the scene with the brief's stops.
		var ramp = e.get("color_ramp")
		var stops := stops_of(ramp) if ramp is Gradient else []
		check("%s.color_ramp" % emitter_name, ramp is Gradient and embedded(ramp) and same_stops(stops, color_ramps[emitter_name]),
			{"expected": str(color_ramps[emitter_name]), "read_back": str(stops), "type": str(ramp), "in_scene_file": embedded(ramp) if ramp is Resource else false})

		check("%s.material" % emitter_name, e.material == null, {"read_back": str(e.material), "expected": "none (mix blend)"})
		var tex = e.get("texture")
		textures.append(tex)
		check("%s.texture" % emitter_name, tex is GradientTexture2D and embedded(tex), {"read_back": str(tex), "resource_path": tex.resource_path if tex is Resource else ""})

	# --- A3 "Draw": every emitter uses one GradientTexture2D defined in the scene file ---
	var one: bool = textures.size() == ORDER.size() and textures[0] is GradientTexture2D
	for t in textures:
		one = one and is_same(t, textures[0])
	check("texture-shared", one, {"emitters": textures.size(), "same_object": one})
	if textures.size() > 0 and textures[0] is GradientTexture2D:
		var tex: GradientTexture2D = textures[0]
		for prop in disc:
			check("texture.%s" % prop, same(tex.get(prop), disc[prop]), {"expected": shown(disc[prop]), "read_back": shown(tex.get(prop))})
		var g_stops := stops_of(tex.gradient)
		check("texture.gradient", tex.gradient != null and embedded(tex.gradient) and same_stops(g_stops, disc_stops),
			{"expected": str(disc_stops), "read_back": str(g_stops), "in_scene_file": embedded(tex.gradient)})

	print("JUMP PUFF CONFIG: %d checks / %d failures" % [results.size(), failures])
	puff.free()
	quit(1 if failures else 0)

extends Node2D
# A6 Effect A frame-strip fixture (CHANGE-BRIEF A5). Not part of the game.
# It instances the real level (res://game/main.tscn, left in MENU so nothing moves and the player
# stays at the spawn, off camera) for the B1 rooftop art, puts the session's camera where the game
# puts it for a player at x 1105 (session.gd: x = player.x + 100, y stays 180), hides the HUD (in
# MENU its tint and card sit over the art), and adds a JumpPuff to the level node at (1105, 280)
# on frame 10, and again on frame 25 when `retrigger` is on. Each puff is added in a physics tick,
# as `jumped` is emitted in the game, so it is simulated and drawn in that same frame.
# Frame N here is the preview's N-th drawn frame, counted from 0 (file N of a Movie Maker strip).
# Capture with a window (30 fps): add `-- retrigger` to the command to turn the export on.
#   godot --path godot --write-movie <absolute dir>/frame.png --fixed-fps 30 --quit-after 60 res://previews/jump_puff_preview.tscn
# Watching by eye (no capture): `-- loop` adds an unseeded puff every LOOP_SECONDS of game time, so
# repeats show the brief's variation; each loop puff is freed after LOOP_SECONDS.
const JumpPuff = preload("res://effects/jump_puff.tscn")
const AT := Vector2(1105, 280)                  # on the B1 ledge (x 1060-1150, top at y 280)
const CAMERA := Vector2(AT.x + 100.0, 180.0)
const TRIGGER_FRAME := 10
const RETRIGGER_FRAME := 25
const SEEDS := [1105, 2805]  # preview only (CHANGE-BRIEF A3): fixed seeds on this scene's own instances
const LOOP_SECONDS := 1.2
@export var retrigger := false
@export var loop := false
@onready var game: Node2D = $WalkerJumpman
var frame := 0               # frames drawn so far
var fired := 0
var loop_clock := 0.0

func _ready() -> void:
	if "retrigger" in OS.get_cmdline_user_args():
		retrigger = true
	if "loop" in OS.get_cmdline_user_args():
		loop = true
	game.camera.position = CAMERA
	game.hud.visible = false

func _physics_process(delta: float) -> void:
	if loop:
		loop_clock += delta
		if loop_clock >= LOOP_SECONDS:
			loop_clock = 0.0
			_spawn_loop()
		return
	var due := [TRIGGER_FRAME, RETRIGGER_FRAME] if retrigger else [TRIGGER_FRAME]
	# `>=`, not `==`: in a live window the physics ticks and drawn frames are not one-to-one, so a
	# tick can miss frame N exactly. Under --fixed-fps 30 every frame runs two ticks, so the first
	# tick of frame N fires, as before.
	if fired < due.size() and frame >= due[fired]:
		_spawn(SEEDS[fired])
		fired += 1

func _spawn_loop() -> void:
	var puff: Node2D = JumpPuff.instantiate()
	puff.position = AT
	game.add_child(puff)
	get_tree().create_timer(LOOP_SECONDS).timeout.connect(puff.queue_free)

func _process(_delta: float) -> void:
	frame += 1

func _spawn(seed_base: int) -> void:
	var puff: Node2D = JumpPuff.instantiate()
	var live := []
	for i in puff.get_child_count():
		var emitter: CPUParticles2D = puff.get_child(i)
		emitter.use_fixed_seed = true
		emitter.seed = seed_base + i
		live.append(emitter.emitting)
	puff.position = AT
	game.add_child(puff)
	print("preview: JumpPuff %d added at %s on frame %d (emitting %s, seeds from %d)" % [fired + 1, AT, frame, live, seed_base])

extends Node2D

const Player = preload("res://features/player/player.gd")
const Hud = preload("res://ui/hud.gd")
enum State { MENU, PLAYING, PAUSED, DYING, COMPLETE }
var state: State = State.MENU
var player: CharacterBody2D
var camera: Camera2D
var hud: Control
var level: Dictionary
var hazard_areas: Array[Area2D] = []
var goal: Area2D
var deaths: int = 0
var elapsed: float = 0.0
var retry_remaining: float = 0.0
var death_reason: String = ""
var last_finish_time: float = 0.0
var test_mode: bool = false
var contact_settle_ticks: int = 0
var survivors: Array = []       # [{area, type, rescued, x, y}] — the trapped survivors
var rescued_count: int = 0      # how many rescued this attempt
var locked_cue_ticks: int = 0   # frames left to flash the "rescue everyone" cue
var saved_popup_ticks: int = 0  # frames left to show the "SAVED!" popup
var saved_popup_pos: Vector2 = Vector2.ZERO
const EXTINGUISH_TICKS := 240          # 4 s @ 60 Hz for the fire to fully die (half by 2 s)
var fire_active: bool = true           # lethal + blocks the rescue until FULLY hosed
var extinguish_ticks: int = 0          # frames until the fire is out (240 = full, 0 = out)
var water_ticks: int = 0               # frames the water visual keeps pouring (lingers ~1 s)
var near_fire: bool = false            # player in hose range this frame (for the prompt)
# Rescue toss (visual only): the rescued survivor is grabbed, flung sky-high, and drops into
# the bag. Game state (rescued, counts) changes at the touch, before any of this is drawn.
const GRAB_TICKS := 15                 # grab pose, survivor held at the window
const TOSS_UP_TICKS := 30              # flying up
const TOSS_DOWN_TICKS := 30            # dropping into the bag
const TOSS_HEIGHT := 150.0
var flights: Array = []                # [{type, from: Vector2, t: int, launch, apex}]
const FIRE_DEATH_HOLD := 2.0          # s; was 0.55 (A1), 0.9 (playtest 2); 2.0 after playtest 3
const BOW_TICKS := 75                  # the bow shows ~1.2 s before the "Rescue complete" card covers him
var complete_ticks: int = 0
# Audio (CHANGE-BRIEF event-to-sound map). Every sound plays AFTER the state change it reports;
# nothing reads a sound or a mute flag, so a missing or muted sound never changes what happens.
const SFX_FILES := {"jump": "sfx_jump", "hose": "sfx_hose", "rescue": "sfx_rescue",
	"burn": "sfx_burn", "win": "sfx_win"}
const MUSIC_FILE := "res://audio/music_loop.ogg"
const MUSIC_DIP_DB := -12.0            # music level under the burn sound while DYING
var sfx_players := {}
var sfx_counts := {}                   # plays per sound id (read by tests/test_audio.gd)
var sfx_log: Array = []                # [{id, state, tick}] per play, so tests can check the order
var music: AudioStreamPlayer
const FIRE_SINGLE := preload("res://art/env/fire_single.png")   # ENV-FIRE-A
const FIRE_WIDE := preload("res://art/env/fire_wide.png")       # ENV-FIRE-B
const FIRE_TALL := preload("res://art/env/fire_tall.png")       # ENV-FIRE-Bb

func _ready() -> void:
	process_physics_priority = 10
	level = JSON.parse_string(FileAccess.get_file_as_string("res://levels/first_steps.json"))
	_setup_input()
	for entry in level.solids:
		_add_solid(Rect2(entry[0], entry[1], entry[2], entry[3]))
	_add_solid(Rect2(-32, 0, 32, 430))
	_add_solid(Rect2(level.width, 0, 32, 430))
	for entry in level.hazards:
		hazard_areas.append(_add_area(Rect2(entry[0], entry[1], entry[2], entry[3]), 8, true))
	var f: Array = level.finish
	goal = _add_area(Rect2(f[0], f[1], f[2], f[3]), 16, false)
	for entry in level.survivors:
		var area := _add_area(Rect2(entry[0] - 8.0, entry[1] - 22.0, 16.0, 22.0), 32, false)
		survivors.append({"area": area, "type": String(entry[2]), "rescued": false, "x": float(entry[0]), "y": float(entry[1])})
	player = Player.new()
	add_child(player)
	player.reset_at(Vector2(level.spawn[0], level.spawn[1]))
	camera = Camera2D.new()
	camera.position = Vector2(320, 180)
	add_child(camera)
	# ENV-BG: the generated skyline, fixed behind everything (a distant backdrop, so it doesn't scroll).
	var bg_layer := CanvasLayer.new()
	bg_layer.layer = -1
	add_child(bg_layer)
	var bg := TextureRect.new()
	bg.texture = load("res://art/env/env_bg.png")
	bg.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
	bg.stretch_mode = TextureRect.STRETCH_SCALE
	bg.size = Vector2(640, 360)
	bg_layer.add_child(bg)
	_setup_audio()
	player.jumped.connect(func(): play_sfx("jump"))
	var layer := CanvasLayer.new()
	add_child(layer)
	hud = Hud.new()
	hud.game = self
	layer.add_child(hud)
	get_window().focus_exited.connect(_on_focus_lost)
	queue_redraw()

func _setup_input() -> void:
	var actions := {"move_left": [KEY_A, KEY_LEFT], "move_right": [KEY_D, KEY_RIGHT], "jump": [KEY_SPACE], "pause": [KEY_ESCAPE, KEY_P], "restart": [KEY_R], "confirm": [KEY_ENTER], "menu": [KEY_M], "water": [KEY_W], "mute_music": [KEY_N], "mute_sfx": [KEY_B]}
	for action in actions:
		if InputMap.has_action(action):
			continue
		InputMap.add_action(action)
		for key in actions[action]:
			var event := InputEventKey.new()
			event.physical_keycode = key
			InputMap.action_add_event(action, event)

func _add_solid(rect: Rect2) -> void:
	var body := StaticBody2D.new()
	body.position = rect.position + rect.size / 2
	body.collision_layer = 1
	body.collision_mask = 2
	var shape := RectangleShape2D.new()
	shape.size = rect.size
	var collision := CollisionShape2D.new()
	collision.shape = shape
	body.add_child(collision)
	add_child(body)

func _add_area(rect: Rect2, layer: int, spikes: bool) -> Area2D:
	var area := Area2D.new()
	area.position = rect.position
	area.collision_layer = layer
	area.collision_mask = 2
	if spikes:
		# Three exact triangular trigger silhouettes; no oversized invisible box.
		for i in range(3):
			var triangle := CollisionPolygon2D.new()
			var x := float(i) * rect.size.x / 3.0
			triangle.polygon = PackedVector2Array([Vector2(x, rect.size.y), Vector2(x + 4, 0), Vector2(x + 8, rect.size.y)])
			area.add_child(triangle)
	else:
		var collision := CollisionShape2D.new()
		var shape := RectangleShape2D.new()
		shape.size = rect.size
		collision.shape = shape
		collision.position = rect.size / 2.0
		area.add_child(collision)
	add_child(area)
	return area

func start_session() -> void:
	if state == State.PLAYING:
		return
	deaths = 0
	restart_attempt()

func restart_attempt() -> void:
	state = State.PLAYING
	elapsed = 0.0
	retry_remaining = 0.0
	# Area2D overlaps are physics-step snapshots. Discard pre-teleport contacts
	# until the broadphase has observed the reset, preventing a phantom second death.
	contact_settle_ticks = 2
	player.reset_at(Vector2(level.spawn[0], level.spawn[1]))
	player.enabled = true
	camera.position = Vector2(320, 180)
	rescued_count = 0
	locked_cue_ticks = 0
	saved_popup_ticks = 0
	fire_active = true
	extinguish_ticks = 0
	water_ticks = 0
	flights.clear()
	for s in survivors:
		s.rescued = false
		s.area.set_deferred("monitoring", true)

# Blocking-fire height in px: full until hosing starts, then shrinks linearly to 0
# over EXTINGUISH_TICKS (half by 2 s). Drives both the flame visual and the kill-zone.
func fire_height() -> float:
	if not fire_active or not level.has("blocking_fire"):
		return 0.0
	var full: float = float(level.blocking_fire[3])
	if extinguish_ticks > 0:
		return full * float(extinguish_ticks) / float(EXTINGUISH_TICKS)
	return full

func set_paused(value: bool) -> void:
	if value and state == State.PLAYING:
		state = State.PAUSED
		player.enabled = false
	elif not value and state == State.PAUSED:
		state = State.PLAYING
		player.enabled = true
		player.require_jump_release = true
		player.jump_request_tick = -1000

func _on_focus_lost() -> void:
	if not test_mode:
		set_paused(true)

func resolve_contacts(fatal: bool, finished: bool) -> void:
	if state != State.PLAYING:
		return
	if fatal:
		state = State.DYING
		deaths += 1
		retry_remaining = 0.55
		player.enabled = false
		player.velocity = Vector2.ZERO
		if death_reason == "The fire got you.":
			player.show_pose("burned")
			play_sfx("burn")
			retry_remaining = FIRE_DEATH_HOLD  # burned pose + DEVASTATED pop-up stay up; R skips the wait
	elif finished:
		state = State.COMPLETE
		last_finish_time = elapsed
		player.enabled = false
		player.velocity = Vector2.ZERO
		player.show_pose("celebrate")
		complete_ticks = 0
		play_sfx("win")

func _physics_process(delta: float) -> void:
	if state == State.DYING:
		retry_remaining -= delta
		if retry_remaining <= 0:
			restart_attempt()
	elif state == State.PLAYING:
		elapsed += delta
		var fell := player.position.y > float(level.fall_y)
		var timed_out := elapsed >= float(level.time_limit)
		var hit_fire := false
		for hazard in hazard_areas:
			if hazard.overlaps_body(player):
				hit_fire = true
		# The blocking fire is lethal + blocks the path until FULLY hosed. Its kill-zone
		# shrinks from the top with the flames (see fire_height), but the base stays lethal
		# until the fire is completely out -- so walking in mid-extinguish still kills.
		if fire_active and level.has("blocking_fire"):
			var bf0: Array = level.blocking_fire
			var fire_top: float = (float(bf0[1]) + float(bf0[3])) - fire_height()
			var half_w: float = Player.BOX.x / 2.0
			if player.position.x + half_w > float(bf0[0]) and player.position.x - half_w < float(bf0[0]) + float(bf0[2]) and player.position.y > fire_top and player.position.y - Player.BOX.y < float(bf0[1]) + float(bf0[3]):
				hit_fire = true
		var fatal := fell or timed_out or hit_fire
		if fatal:
			death_reason = "Out of time!" if timed_out else ("You fell." if fell else "The fire got you.")
		# Hose: tap W within range of the blocking fire -> water pours ~4 s -> fire out.
		near_fire = false
		if fire_active and level.has("blocking_fire"):
			var bf: Array = level.blocking_fire
			near_fire = player.is_on_floor() and player.position.x > float(bf[0]) - 50.0 and player.position.x < float(bf[0]) + float(bf[2]) + 10.0 and player.position.y < float(bf[1]) + float(bf[3]) + 20.0 and player.position.y > float(bf[1]) - 40.0
			var water: bool = player.test_water_pressed if player.test_control else Input.is_action_just_pressed("water")
			if player.test_control:
				player.test_water_pressed = false
			if water and near_fire and extinguish_ticks == 0:
				extinguish_ticks = EXTINGUISH_TICKS
				water_ticks = EXTINGUISH_TICKS + 60  # water lingers ~1 s after it is out
				play_sfx("hose")
		if extinguish_ticks > 0:
			extinguish_ticks -= 1
			if extinguish_ticks == 0:
				fire_active = false
		if water_ticks > 0:
			water_ticks -= 1
		player.hosing = water_ticks > 0
		# Touch to rescue -- only while NOT in a fatal state, so you can't rescue THROUGH fire.
		if not fatal:
			for s in survivors:
				if not s.rescued and s.area.overlaps_body(player):
					s.rescued = true
					s.area.set_deferred("monitoring", false)
					rescued_count += 1
					player.rescued = rescued_count
					player.bag_types.append(s.type)
					player.bag_in_flight += 1
					player.play_actions([["grab", GRAB_TICKS], ["toss", TOSS_UP_TICKS]])
					flights.append({"type": s.type, "from": Vector2(s.x, s.y), "t": 0})
					play_sfx("rescue")
					saved_popup_ticks = 55
					saved_popup_pos = Vector2(s.x - 18.0, s.y - 34.0)
		var all_rescued := rescued_count >= survivors.size()
		var at_exit := goal.overlaps_body(player) and player.is_on_floor()
		if at_exit and not all_rescued:
			locked_cue_ticks = 45  # flash "rescue everyone first"
		if locked_cue_ticks > 0:
			locked_cue_ticks -= 1
		if saved_popup_ticks > 0:
			saved_popup_ticks -= 1
		if contact_settle_ticks > 0:
			contact_settle_ticks -= 1
		else:
			# Exit completes only when BOTH survivors are rescued AND reached on foot.
			# State machine unchanged; only the COMPLETE condition gains "both rescued".
			resolve_contacts(fatal, at_exit and all_rescued)
		camera.position.x = clampf(player.position.x + 100, 320, float(level.width) - 320)
	if state == State.COMPLETE:
		complete_ticks += 1
	for fl in flights:
		fl.t += 1
		if fl.t == GRAB_TICKS:  # toss starts: launch from his raised hand, straight up
			fl.launch = player.position + Vector2(0.0, -62.0)
			fl.apex = fl.launch + Vector2(0.0, -TOSS_HEIGHT)
		if fl.t >= GRAB_TICKS + TOSS_UP_TICKS + TOSS_DOWN_TICKS:
			player.bag_in_flight = maxi(player.bag_in_flight - 1, 0)
			player.queue_redraw()
	flights = flights.filter(func(fl): return fl.t < GRAB_TICKS + TOSS_UP_TICKS + TOSS_DOWN_TICKS)
	if is_instance_valid(hud):
		hud.queue_redraw()
	queue_redraw()  # refresh the level's own dynamic draw: survivors vanish, SAVED! animates, exit unlocks

func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventKey and event.echo:
		return
	if event.is_action_pressed("mute_music"):
		_toggle_mute("Music")
	elif event.is_action_pressed("mute_sfx"):
		_toggle_mute("SFX")
	elif event.is_action_pressed("confirm"):
		if state in [State.MENU, State.COMPLETE]:
			start_session()
		elif state == State.PAUSED:
			set_paused(false)
	elif event.is_action_pressed("pause"):
		set_paused(state != State.PAUSED)
	elif event.is_action_pressed("restart") and state in [State.PLAYING, State.PAUSED, State.DYING]:
		restart_attempt()
	elif event.is_action_pressed("menu") and state in [State.PAUSED, State.COMPLETE]:
		state = State.MENU
		player.enabled = false
	elif event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		if Rect2(220, 215, 200, 34).has_point(hud.get_local_mouse_position()):
			if state in [State.MENU, State.COMPLETE]:
				start_session()
			elif state == State.PAUSED:
				set_paused(false)

func _draw() -> void:
	if level.is_empty():
		return
	var font := ThemeDB.fallback_font
	var ink := Color("25354a")
	# All visual assets are original Godot vector drawing, not recovered art.
	# The A1 cream sky, grid, and hills are replaced by the generated ENV-BG (see _ready).
	# Burning buildings — decorative facades drawn BEHIND the ledges (no collision).
	for b in level.get("buildings", []):
		var bl := Rect2(b[0], b[1], b[2], b[3])
		draw_rect(bl, Color("e0cdaf"))                                         # very light brown wall (contrast for dark figures)
		draw_rect(Rect2(bl.position, Vector2(bl.size.x, 5)), Color("a3855f"))  # roof cap (medium brown)
		draw_rect(bl, Color(0.96, 0.46, 0.16, 0.18))                           # warm fire glow (keeps the burning read)
		for wx in range(int(bl.position.x) + 18, int(bl.end.x) - 14, 84):
			for wy in range(int(bl.position.y) + 16, int(bl.end.y) - 24, 34):
				draw_rect(Rect2(wx, wy, 13, 17), Color("6f5c46"))
				draw_rect(Rect2(wx + 2, wy + 2, 9, 13), Color("f2ecd8"))
	for entry in level.solids:
		var r := Rect2(entry[0], entry[1], entry[2], entry[3])
		# Light concrete with a dark outline: the A1 navy (#25354a) vanished against ENV-BG's dark fog (#2c3547).
		draw_rect(Rect2(r.position - Vector2(1, 1), r.size + Vector2(2, 2)), Color("1b2230"))
		draw_rect(r, Color("b8b2a6"))
		draw_rect(Rect2(r.position, Vector2(r.size.x, 4)), Color("438e7d"))
		for x in range(int(r.position.x)+12, int(r.end.x), 24):
			draw_line(Vector2(x, r.position.y+12), Vector2(x+7, r.position.y+19), Color("8f897d"), 1)
	# Fire hazard drawn as bold flames, data-driven from the hazard rect. The VISUAL is
	# enlarged for readability but the COLLISION (the rect, built in _add_area) is
	# UNCHANGED, so the jump-over margins verified by flame-clearance-positive still
	# hold. Flame tips stay below the player's jump clearance, so a cleared jump does
	# not clip the visual.
	# ENV-FIRE (generated flames) drawn over each hazard rect: the wide street fire uses the wide
	# cluster, small ones a row of single flames. Visual only: the COLLISION is the rect built in
	# _add_area, unchanged, so the flame-clearance tests still hold. The art reaches ~8 px above the
	# rect, like A1's code-drawn tips, so it can look touched without killing (forgiving).
	for entry in level.hazards:
		var hr := Rect2(entry[0], entry[1], entry[2], entry[3])
		var vis := Rect2(hr.position.x - 2.0, hr.position.y - 8.0, hr.size.x + 4.0, hr.size.y + 8.0)
		if hr.size.x >= 40.0:
			draw_texture_rect(FIRE_WIDE, vis, false)
		else:
			var n: int = maxi(1, int(round(vis.size.x / (vis.size.y * 0.55))))
			for k in range(n):
				draw_texture_rect(FIRE_SINGLE, Rect2(vis.position.x + vis.size.x * k / n, vis.position.y, vis.size.x / n, vis.size.y), false)
	# Finish: a FIRE-ESCAPE window. Data-driven from level.finish; LOCKED until both
	# survivors are rescued, then it brightens with a "JUMP OUT" prompt.
	var fr := Rect2(level.finish[0], level.finish[1], level.finish[2], level.finish[3])
	var all_saved := rescued_count >= survivors.size()
	var glow := Color("e8792b") if all_saved else Color("6b7683")
	var pane := Color("ffe08a") if all_saved else Color("aeb7c2")
	draw_rect(Rect2(fr.position.x - 3.0, fr.position.y - 3.0, fr.size.x + 6.0, fr.size.y + 6.0), glow)
	draw_rect(fr, ink)
	draw_rect(Rect2(fr.position.x + 2.0, fr.position.y + 2.0, fr.size.x - 4.0, fr.size.y - 4.0), pane)
	draw_rect(Rect2(fr.position.x + fr.size.x / 2.0 - 1.0, fr.position.y + 2.0, 2.0, fr.size.y - 4.0), ink)
	draw_rect(Rect2(fr.position.x + 2.0, fr.position.y + fr.size.y / 2.0 - 1.0, fr.size.x - 4.0, 2.0), ink)
	draw_rect(Rect2(fr.position.x - 2.0, fr.end.y - 2.0, fr.size.x + 4.0, 3.0), ink)
	if all_saved:
		_label(Vector2(fr.position.x - 22.0, fr.position.y - 14.0), "JUMP OUT →", 13, Color("7fe0b0"))
	else:
		var lx: float = fr.position.x + fr.size.x / 2.0
		var ly: float = fr.position.y + fr.size.y / 2.0
		draw_rect(Rect2(lx - 4.0, ly - 1.0, 8.0, 7.0), Color("3a2f1a"))
		draw_arc(Vector2(lx, ly - 1.0), 3.0, PI, TAU, 8, Color("3a2f1a"), 1.5)
		_label(Vector2(fr.position.x - 40.0, fr.position.y - 14.0), "FIRE ESCAPE", 13, Color("f6f3ec"))
	if locked_cue_ticks > 0:
		_label(Vector2(fr.position.x - 66.0, fr.position.y - 30.0), "Rescue everyone first!", 14, Color("ff7a66"))
	# "SAVED!" popup that rises + fades at the moment of a rescue.
	if saved_popup_ticks > 0:
		var pa: float = clampf(float(saved_popup_ticks) / 55.0, 0.0, 1.0)
		var rise: float = float(55 - saved_popup_ticks) * 0.35
		_label(saved_popup_pos - Vector2(0.0, rise), "SAVED!", 16, Color(0.5, 0.88, 0.69, pa))
	# Trapped survivors (un-rescued only), each with a HELP! bubble to draw the player in.
	for s in survivors:
		if s.rescued:
			continue
		var sx: float = s.x
		var sy: float = s.y
		# rescue window: thin frame + DARK interior + soft fire backlight (a clear opening, not a flat box)
		draw_rect(Rect2(sx - 13.0, sy - 33.0, 26.0, 33.0), ink)                             # frame
		draw_rect(Rect2(sx - 11.0, sy - 31.0, 22.0, 31.0), Color("241d1b"))                 # dark room interior
		draw_rect(Rect2(sx - 11.0, sy - 15.0, 22.0, 15.0), Color(0.98, 0.55, 0.22, 0.30))   # soft fire glow, low
		if s.type == "dog":
			# clearly a dog: tail + body + four legs + head + snout + ear (dark outline, warm fill)
			var dg := Color("d59243")
			draw_colored_polygon(PackedVector2Array([Vector2(sx-7,sy-9), Vector2(sx-11,sy-14), Vector2(sx-9,sy-14.5), Vector2(sx-6,sy-8)]), ink)
			draw_colored_polygon(PackedVector2Array([Vector2(sx-7,sy-9), Vector2(sx-10,sy-13), Vector2(sx-8.5,sy-13.5), Vector2(sx-6,sy-8.5)]), dg)
			for lx in [-6.0, -2.5, 1.5, 4.5]:
				draw_rect(Rect2(sx + lx, sy - 6.0, 2.6, 6.0), ink)
				draw_rect(Rect2(sx + lx + 0.5, sy - 5.5, 1.6, 5.0), dg)
			draw_rect(Rect2(sx - 8.0, sy - 12.0, 14.0, 7.0), ink)
			draw_rect(Rect2(sx - 7.0, sy - 11.0, 12.0, 5.5), dg)
			draw_colored_polygon(PackedVector2Array([Vector2(sx+3.5,sy-15.5), Vector2(sx+4.5,sy-11), Vector2(sx+7,sy-13)]), ink)
			draw_circle(Vector2(sx + 6.0, sy - 12.0), 4.2, ink)
			draw_circle(Vector2(sx + 6.0, sy - 12.0), 3.2, dg)
			draw_rect(Rect2(sx + 7.5, sy - 12.0, 4.0, 3.0), ink)
			draw_rect(Rect2(sx + 7.8, sy - 11.6, 3.6, 2.2), dg)
			draw_circle(Vector2(sx + 11.0, sy - 10.8), 0.9, ink)
			draw_circle(Vector2(sx + 6.2, sy - 12.6), 0.9, ink)
		else:
			# clearly a person: head+face, torso, one arm RAISED waving, two legs (dark outline, bright fill)
			var shirt := Color("46a0e0")
			var face := Color("f2c9a0")
			draw_rect(Rect2(sx - 3.6, sy - 8.0, 3.2, 8.0), ink)
			draw_rect(Rect2(sx + 0.4, sy - 8.0, 3.2, 8.0), ink)
			draw_rect(Rect2(sx - 3.1, sy - 7.5, 2.2, 7.0), Color("2b3a55"))
			draw_rect(Rect2(sx + 0.9, sy - 7.5, 2.2, 7.0), Color("2b3a55"))
			draw_rect(Rect2(sx - 5.0, sy - 19.0, 10.0, 12.0), ink)
			draw_rect(Rect2(sx - 4.0, sy - 18.0, 8.0, 10.0), shirt)
			draw_rect(Rect2(sx - 7.0, sy - 18.0, 3.0, 9.0), ink)
			draw_rect(Rect2(sx - 6.5, sy - 17.0, 2.0, 8.0), face)
			draw_rect(Rect2(sx + 3.2, sy - 27.0, 3.0, 11.0), ink)
			draw_rect(Rect2(sx + 3.7, sy - 26.0, 2.0, 10.0), face)
			draw_circle(Vector2(sx + 4.7, sy - 27.5), 2.3, ink)
			draw_circle(Vector2(sx + 4.7, sy - 27.5), 1.5, face)
			draw_circle(Vector2(sx, sy - 22.5), 5.2, ink)
			draw_circle(Vector2(sx, sy - 22.5), 4.2, face)
			draw_rect(Rect2(sx - 4.3, sy - 27.0, 8.6, 3.2), Color("3a2f1a"))
			draw_circle(Vector2(sx - 1.6, sy - 23.0), 0.9, ink)
			draw_circle(Vector2(sx + 1.6, sy - 23.0), 0.9, ink)
			draw_rect(Rect2(sx - 1.5, sy - 20.0, 3.0, 1.1), Color("a23e36"))
		# HELP! speech bubble (enlarged) with a pointer/tail down to the survivor
		var buby := sy - 58.0
		var bubx := sx - 23.0
		draw_colored_polygon(PackedVector2Array([Vector2(sx-5,buby+17), Vector2(sx+7,buby+17), Vector2(sx+1,buby+27)]), ink)
		draw_rect(Rect2(bubx - 2.0, buby - 2.0, 50.0, 22.0), ink)
		draw_rect(Rect2(bubx, buby, 46.0, 18.0), Color("fff2b0"))
		draw_colored_polygon(PackedVector2Array([Vector2(sx-3,buby+16), Vector2(sx+5,buby+16), Vector2(sx+1,buby+24)]), Color("fff2b0"))
		draw_string(font, Vector2(bubx + 6.0, buby + 15.0), "HELP!", HORIZONTAL_ALIGNMENT_LEFT, -1, 15, Color("a23e36"))
	# Blocking fire at the person's window (big, lethal until hosed) + water stream + prompt.
	if level.has("blocking_fire"):
		var bf: Array = level.blocking_fire
		var bx: float = bf[0]
		var byy: float = bf[1]
		var bw: float = bf[2]
		var bbase: float = byy + float(bf[3])
		if fire_active:
			# ENV-FIRE tall cluster; it shrinks from the top with fire_height() as it's hosed.
			var fh: float = fire_height()
			draw_texture_rect(FIRE_TALL, Rect2(bx - 8.0, bbase - fh - 10.0, bw + 16.0, fh + 10.0), false)
		if water_ticks > 0:
