		for prop in want_mat:
			var got = mat.get(prop)
			check("%s.process_material.%s" % [emitter_name, prop], same(got, want_mat[prop]), {"expected": shown(want_mat[prop]), "read_back": shown(got)}, prop in NOT_IN_A)

